// sum19.cu
// Contract: on Volta or newer, exactly physical lanes 0..18
// of one full warp call this function once for this invocation.
__device__ __forceinline__ float sum19(float value)
{
    unsigned lane;
    asm("mov.u32 %0, %%laneid;" : "=r"(lane));

    constexpr unsigned mask = 0x0007ffffu;
    float sum = value;

    #pragma unroll
    for (int offset = 16; offset >= 1; offset >>= 1) {
        const unsigned partner = lane + static_cast<unsigned>(offset);
        const bool has_partner = partner < 19u;
        const int source = static_cast<int>(has_partner ? partner : lane);

        const float other = __shfl_sync(mask, sum, source, 32);
        if (has_partner) {
            sum = __fadd_rn(sum, other);
        }
    }

    return __shfl_sync(mask, sum, 0, 32);
}
```
Yes. A caller with no partner still executes the shuffle collective, using its own lane as the source, but skips the addition. Every caller executes all five reduction shuffles and the final broadcast.

A count distinguishes full from empty even when the read and write positions coincide, so all 17 slots are usable. Push rejects overflow without changing the queue, and pop rejects an empty queue without changing its output argument. This complete C++17 program also tests wraparound while data remains queued.

```cpp
#include <array>
#include <cassert>
#include <cstddef>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (count_ == capacity) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++count_;
        return true;
    }

    bool pop(int& value) {
        if (count_ == 0) return false;
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return true;
    }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    BoundedFIFO queue;
    int value = -99;
    assert(!queue.pop(value));
    assert(value == -99);

    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
    }
    assert(!queue.push(999));
    for (int i = 0; i < 17; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(!queue.pop(value));

    // Fill, partially drain, then wrap the write position.
    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
    }
    for (int i = 0; i < 8; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    for (int i = 17; i < 25; ++i) {
        assert(queue.push(i));
    }
    assert(!queue.push(999));
    for (int i = 8; i < 25; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(!queue.pop(value));
}
```

