// sum_valid.cu
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

static void check(cudaError_t status, const char* operation)
{
    if (status != cudaSuccess) {
        std::fprintf(stderr, "%s: %s\n", operation,
                     cudaGetErrorString(status));
        std::exit(EXIT_FAILURE);
    }
}
#define CHECK(call) check((call), #call)

__global__ void sum_valid(const float* input, float* output, int valid)
{
    // Contract: exactly <<<1, 96>>>; 0 <= valid <= 96.
    // input contains at least valid readable floats;
    // output contains one writable float, separate from input.
    __shared__ float values[96];
    const unsigned tid = threadIdx.x;

    float value = 0.0f;
    if (tid < static_cast<unsigned>(valid)) {
        value = input[tid];
    }
    values[tid] = value;

    __syncthreads();

    if (tid == 0) {
        float sum = 0.0f;
        for (int i = 0; i < valid; ++i) {
            sum = __fadd_rn(sum, values[i]);
        }
        output[0] = sum;
    }
}

int main(int argc, char** argv)
{
    int valid = 70;
    if (argc > 2) {
        std::fprintf(stderr, "Usage: %s [valid: 0..96]\n", argv[0]);
        return EXIT_FAILURE;
    }
    if (argc == 2) {
        char* end = nullptr;
        long parsed = std::strtol(argv[1], &end, 10);
        if (end == argv[1] || *end != '\0' || parsed < 0 || parsed > 96) {
            std::fprintf(stderr, "valid must be 0..96\n");
            return EXIT_FAILURE;
        }
        valid = static_cast<int>(parsed);
    }

    cudaStream_t stream;
    cudaEvent_t done;
    CHECK(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    CHECK(cudaEventCreateWithFlags(&done, cudaEventDisableTiming));

    float *host_input, *host_output, *device_input, *device_output;
    CHECK(cudaMallocHost(reinterpret_cast<void**>(&host_input),
                         96 * sizeof(float)));
    CHECK(cudaMallocHost(reinterpret_cast<void**>(&host_output),
                         sizeof(float)));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&device_input),
                     96 * sizeof(float)));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&device_output),
                     sizeof(float)));

    for (int i = 0; i < 96; ++i) host_input[i] = float(i + 1);
    if (valid > 0) {
        CHECK(cudaMemcpyAsync(device_input, host_input,
                              valid * sizeof(float),
                              cudaMemcpyHostToDevice, stream));
    }
    // Always launch, including valid == 0. No host output initialization.
    sum_valid<<<1, 96, 0, stream>>>(device_input, device_output, valid);
    CHECK(cudaGetLastError()); // Immediate launch errors only.
    CHECK(cudaMemcpyAsync(host_output, device_output, sizeof(float),
                          cudaMemcpyDeviceToHost, stream));
    CHECK(cudaEventRecord(done, stream));
    CHECK(cudaEventSynchronize(done)); // Completion and asynchronous errors.

    const float expected = float(valid * (valid + 1) / 2);
    const bool correct = (*host_output == expected);
    std::printf("valid=%d sum=%.9g expected=%.9g\n",
                valid, *host_output, expected);

    CHECK(cudaFree(device_input));
    CHECK(cudaFree(device_output));
    CHECK(cudaFreeHost(host_input));
    CHECK(cudaFreeHost(host_output));
    CHECK(cudaEventDestroy(done));
    CHECK(cudaStreamDestroy(stream));
    return correct ? EXIT_SUCCESS : EXIT_FAILURE;
}
```

